#include <iostream>
#include <algorithm>
#define ll long long
using namespace std;

int a[501];
ll h[1000];

int main()
{
    ll n, m, i, j, k = 1, g;
    cin >> n >> m;
    g = m;
    ll x = 1, y = n;

    if (n == 1)
    {
        cout << 1;
        return 0;
    }

    if (n == 2)
    {
        if (m == 1)
            cout << "1 2";
        else
            cout << "2 1";
        return 0;
    }

    h[1] = 1;
    for (i = 2; i <= n; i++)
        h[i] = h[i - 1] * 2;

    for (i = n - 3; i >= 0; i--)
    {
        if ((2LL << i) >= m && m != 0)
            a[x++] = k;
        else
            a[y--] = k;

        if (h[i] != 0)
            m %= h[i];
        else
            m = 0;

        k++;
    }

    if (g % 2 == 0)
    {
        for (i = y; i >= x; i--)
            a[i] = k++;
    }
    else
    {
        for (i = x; i <= y; i++)
            a[i] = k++;
    }

    for (i = 1; i <= n; i++)
        cout << a[i] << " ";

    cout << endl;
    return 0;
}

